import 'package:flutter/services.dart';
import 'package:math_expressions/math_expressions.dart';
class ScientificCalculatorPage extends StatefulWidget {const ScientificCalculatorPage({super.key});@override State<ScientificCalculatorPage> createState()=>_ScientificCalculatorPageState();}
class _ScientificCalculatorPageState extends State<ScientificCalculatorPage>{
 String expression='',result='0',angle='DEG',format='NORM';bool shift=false;final history=<String>[];
 final keys=[['SHIFT','(',')','DEL','AC'],['sin','cos','tan','√','x²'],['log','ln','abs','π','^'],['7','8','9','÷','%'],['4','5','6','×','−'],['1','2','3','0','+'],['.','Ans','!','=']];
 void press(String k){setState((){if(k=='AC'){expression='';result='0';return;}if(k=='DEL'){if(expression.isNotEmpty)expression=expression.substring(0,expression.length-1);return;}if(k=='SHIFT'){shift=!shift;return;}if(k=='='){calculate();return;}if(k=='Ans'){expression+=result;return;}if(k=='π'){expression+='pi';return;}if(k=='√'){expression+='sqrt(';return;}if(k=='x²'){expression+='^2';return;}if(['sin','cos','tan','log','ln','abs'].contains(k)){final fn=shift?{'sin':'asin','cos':'acos','tan':'atan','log':'10^','ln':'exp','abs':'abs'}[k]!:k;expression+=fn+'(';shift=false;return;}if(k=='÷')expression+='/';else if(k=='×')expression+='*';else if(k=='−')expression+='-';else expression+=k;});}
 String normalize(String s){var v=s.replaceAll('×','*').replaceAll('÷','/').replaceAll('−','-').replaceAll('π','pi');if(angle=='DEG'){v=v.replaceAllMapped(RegExp(r'(sin|cos|tan)\(([-+]?\d+(?:\.\d+)?)\)'),(m)=>m.group(1)!+'(('+m.group(2)!+'*pi/180))');}return v;}
 void calculate(){try{if(expression.isEmpty)return;final parsed=Parser().parse(normalize(expression));final n=parsed.evaluate(EvaluationType.REAL,ContextModel());if(!n.isFinite)throw Exception();result=format=='SCI'?n.toStringAsExponential(8):format.startsWith('FIX')?n.toStringAsFixed(int.tryParse(format.substring(3))??2):n==n.roundToDouble()?n.toInt().toString():n.toStringAsPrecision(12);history.insert(0,expression+' = '+result);if(history.length>100)history.removeLast();shift=false;}catch(_){result='خطأ في التعبير';}}
 Widget key(String k){final special=['SHIFT','DEL','AC','='].contains(k),op=['÷','×','−','+','^','%'].contains(k);final color=k=='='?Theme.of(context).colorScheme.primary:k=='AC'?Theme.of(context).colorScheme.errorContainer:special?Theme.of(context).colorScheme.secondaryContainer:op?Theme.of(context).colorScheme.tertiaryContainer:Theme.of(context).colorScheme.surfaceContainerHighest;return Expanded(child:Padding(padding:const EdgeInsets.all(3),child:AspectRatio(aspectRatio:1.3,child:Material(color:color,borderRadius:BorderRadius.circular(13),child:InkWell(borderRadius:BorderRadius.circular(13),onTap:()=>press(k),child:Center(child:Text(k,style:TextStyle(fontSize:k.length>4?12:17,fontWeight:FontWeight.w800,color:k=='='?Colors.white:Theme.of(context).colorScheme.onSurface))))))));}
