ion=''),icon:const Icon(Icons.clear_all),label:const Text('مسح التعبير'))]),const Text('يدعم الحسابات الأساسية والدوال المثلثية واللوغاريتمية والجذور والأسس. المصفوفات والإحصاء وحل المعادلات ليست مضافة بعد.',style:TextStyle(fontSize:11))]))));
